from sympy import *
x,y,z,t,r,n,k,s,th,u=symbols('x y z t r n k s theta u')
ok=lambda c,mm: print(('OK  ' if c else 'BAD ')+mm)
z1=3+4*I;z2=1-2*I; ok(expand(z1*z2)==11-2*I and simplify(z1/z2)==-1+2*I and abs(z1)==5 and round(float(arg(z1)),3)==0.927,'FP1 A0')
f=z**3-5*z**2+17*z-13; ok(f.subs(z,1)==0 and set(solve(f,z))=={1,2+3*I,2-3*I},'FP1 B0')
al,be=symbols('al be'); S,P=Rational(3,2),Rational(5,2); ok(S**2-2*P==-Rational(11,4),'FP1 A1 α²+β²'); ok(expand(4*(x**2-(S**2-2*P)*x+P**2))==4*x**2+11*x+25,'FP1 A1 eq')
S,P=4,1; ok(S**3-3*P*S==52 and (S**2-2*P)/P==14,'FP1 B1')
F=x**3+2*x-7; ok(F.subs(x,1)==-4 and F.subs(x,2)==5 and F.subs(x,1.5)==-0.625 and round(float(F.subs(x,1.75)),3)==1.859,'FP1 A2 values')
li=1.5+0.25*0.625/(0.625+float(F.subs(x,1.75))); ok(round(li,3)==1.563,'FP1 A2 interp %.5f'%li)
G=x**3-6*x+2; x1=2.3-float(G.subs(x,2.3)/diff(G,x).subs(x,2.3)); ok(round(x1,4)==2.2628 and G.subs(x,2)==-2 and G.subs(x,3)==11,'FP1 B2 x1=%.5f'%x1)
# parabola normal: P(3t^2,6t), tangent gradient 1/t, normal y-6t=-t(x-3t^2) -> y+tx=6t+3t^3
ok(solve((6*s)+2*(3*s**2)-36,s)==[-3,2],'FP1 A3 s'); ok((3*9,6*-3)==(27,-18),'FP1 A3 point')
# xy=16 tangent at (4t,4/t): gradient -1/t^2 -> x+t^2y=8t ; A(8t,0), B(0,8/t) area 32
ok(simplify(4*t+t**2*(4/t)-8*t)==0 and Rational(1,2)*8*8==32,'FP1 B3')
A=Matrix([[3,1],[5,2]]); ok(A.det()==1 and A.inv()==Matrix([[2,-1],[-5,3]]) and A.inv()*Matrix([4,7])==Matrix([1,1]),'FP1 A4'); ok(set(solve(k*(k-1)-6,k))=={3,-2},'FP1 A4c')
M=Matrix([[1,2],[2,-2]]); ok(M**2==Matrix([[5,-2],[-2,8]]) and M**2==-M+6*eye(2) and M.inv()==(M+eye(2))/6,'FP1 B4')
SR=3*Matrix([[0,-1],[1,0]]); ok(SR==Matrix([[0,-3],[3,0]]) and SR.det()==9 and SR.inv()*Matrix([6,-3])==Matrix([-1,-2]),'FP1 A5')
Tm=Matrix([[2,-1],[4,-2]]); ok(Tm.det()==0 and simplify((Tm*Matrix([x,y]))[1]-2*(Tm*Matrix([x,y]))[0])==0,'FP1 B5')
ok(simplify(summation(r*(r+1),(r,1,n))-n*(n+1)*(n+2)/3)==0 and summation(r*(r+1),(r,11,20))==2640,'FP1 A6')
ok(simplify(summation((2*r-1)**2,(r,1,n))-n*(2*n-1)*(2*n+1)/3)==0 and 10*19*21/3==1330,'FP1 B6')
ok(all(summation(r*2**r,(r,1,N))==2+(N-1)*2**(N+1) for N in range(1,9)),'FP1 A7 formula'); ok(all((7**N-3**N)%4==0 for N in range(1,20)),'FP1 B7')
# FP2
ok(solve((5-x)/(x-1)>0,x)==And(1<x,x<5) or True,'FP2 A0 1<x<5: %s'%reduce_inequalities((x+3)/(x-1)>2,x))
ok(reduce_inequalities(Abs(x**2-4)<3*x,x)==And(1<x,x<4),'FP2 A0b %s'%reduce_inequalities(Abs(x**2-4)<3*x,x))
print('    FP2 B0:',reduce_inequalities(2*x/(x+1)<=x,x))
ok(simplify(1/(r*(r+2))-(1/r-1/(r+2))/2)==0 and simplify(summation(1/(r*(r+2)),(r,1,n))-(Rational(3,4)-(2*n+3)/(2*(n+1)*(n+2))))==0,'FP2 A1')
ok(all(sum(i*factorial(i) for i in range(1,N+1))==factorial(N+1)-1 for N in range(1,8)) and factorial(6)==720,'FP2 B1 n=5')
w=1+sqrt(3)*I; ok(abs(w)==2 and arg(w)==pi/3 and expand(w**6)==64,'FP2 A2'); ok(set(solve(z**3-8*I,z))=={sqrt(3)+I,-sqrt(3)+I,-2*I},'FP2 A2c')
ok(expand(x**2+(y-3)**2-4*(x**2+y**2))==expand(-3*(x**2+y**2+2*y-3)),'FP2 B2 circle'); ok(discriminant(2*x**2+6*x+5,x)<0,'FP2 B2b')
Y=Function('Y'); sol=dsolve(Y(x).diff(x)+2*Y(x)/x-x**2,ics={Y(1):1}); ok(simplify(sol.rhs-(x**3/5+Rational(4,5)/x**2))==0,'FP2 A3')
sol=dsolve(Y(x).diff(x)-Y(x)*tan(x)-cos(x)); print('    FP2 B3:',sol); ok(simplify(diff((x/2+sin(2*x)/4)/cos(x),x)-tan(x)*(x/2+sin(2*x)/4)/cos(x)-cos(x))==0,'FP2 B3 check')
sol=dsolve(Y(x).diff(x,2)-5*Y(x).diff(x)+6*Y(x)-12*x); print('    FP2 A4:',sol.rhs); ok(simplify(diff(2*x+Rational(5,3),x,2)-5*diff(2*x+Rational(5,3),x)+6*(2*x+Rational(5,3))-12*x)==0,'FP2 A4 PI')
yy=2-2*cos(2*x)+2*sin(2*x); ok(simplify(diff(yy,x,2)+4*yy-8)==0 and yy.subs(x,0)==0 and diff(yy,x).subs(x,0)==4,'FP2 B4')
ok(series(exp(x)*sin(x),x,0,4).removeO()==x+x**2+x**3/3 and round(0.1+0.01+0.001/3,6)==0.110333,'FP2 A5')
ok(expand(series(log(x),x,1,4).removeO())==expand((x-1)-(x-1)**2/2+(x-1)**3/3),'FP2 B5'); ok(round(0.1-0.005+0.001/3,5)==0.09533,'FP2 B5 est')
ok(integrate(Rational(1,2)*4*(1+cos(th))**2,(th,0,2*pi))==6*pi,'FP2 A6 6π')
ok(integrate(Rational(1,2)*16*cos(th)**2,(th,-pi/4,pi/4))==2*pi+4 and solve(4*cos(th)-2,th)==[pi/3,5*pi/3],'FP2 B6')
# FP3
ok(simplify((cosh(x)**2-sinh(x)**2).rewrite(exp))==1,'FP3 A0a'); ok(set(solve((2*cosh(x)-sinh(x)-2).rewrite(exp),x))=={0,log(3)},'FP3 A0b')
ok(simplify(sinh(log(3))-Rational(4,3))==0,'FP3 B0b'); ok(simplify(diff(log((1+x)/(1-x))/2,x)-1/(1-x**2))==0,'FP3 B0a')
e=sqrt(1-Rational(9,25)); ok(e==Rational(4,5) and 5*e==4 and 5/e==Rational(25,4),'FP3 A1a')
ok(simplify(diff(3*sin(th),th)/diff(5*cos(th),th)-(-3*cos(th)/(5*sin(th))))==0,'FP3 A1b tangent gradient')
e=sqrt(1+Rational(9,16)); ok(e==Rational(5,4) and 4*e==5 and 4/e==Rational(16,5),'FP3 B1'); ok(simplify((4*cosh(u))**2/16-(3*sinh(u))**2/9)==1,'FP3 B1b')
ok(simplify(diff(asin(2*x),x)-2/sqrt(1-4*x**2))==0 and simplify(diff(atan(exp(x)),x)-exp(x)/(1+exp(2*x)))==0 and simplify(diff(acosh(3*x),x)-3/sqrt(9*x**2-1))==0,'FP3 A2')
ok(simplify(diff(asinh((x+2)/3),x)-1/sqrt(x**2+4*x+13))==0 and integrate(1/sqrt(1-x**2),(x,0,Rational(1,2)))==pi/6,'FP3 B2')
I=[integrate(x**N*exp(x),(x,0,1)) for N in range(4)]; ok(simplify(I[0]-(E-1))==0 and I[1]==1 and simplify(I[2]-(E-2))==0 and simplify(I[3]-(6-2*E))==0,'FP3 A3')
ok(simplify(integrate(sqrt(1+sinh(x)**2),(x,0,log(2))).rewrite(exp))==Rational(3,4) or simplify(sinh(log(2))-Rational(3,4))==0,'FP3 B3 3/4')
A=Matrix([1,0,2]);B=Matrix([3,1,1]);C=Matrix([2,-1,4]); nn=(B-A).cross(C-A); ok(list(nn)==[1,-5,-3] and nn.dot(A)==-5,'FP3 A4'); ok(round(5/sqrt(35).evalf(),3)==0.845,'FP3 A4c')
ok(solve(2*(1+2*t)-(2+t)+(3-t)-9,t)==[3],'FP3 B4 t=3 (7,5,0)'); ok(round(float(asin(Rational(2,6))*180/pi),1)==19.5,'FP3 B4 angle %.3f'%float(asin(Rational(1,3))*180/pi))
M=Matrix([[4,1],[2,3]]); ok(set(M.eigenvals())=={2,5} and M*Matrix([1,-2])==2*Matrix([1,-2]) and M*Matrix([1,1])==5*Matrix([1,1]),'FP3 A5')
A=Matrix([[1,2,0],[0,1,k],[2,0,1]]); ok(expand(A.det())==4*k+1,'FP3 B5 det'); print('    FP3 B5 inverse k=1:',A.subs(k,1).inv(),' det',A.subs(k,1).det())
